7	function isNeighbor([x, y]: Cell, [otherX, otherY]: Cell): boolean {
8	  const sameCell = x === otherX && y === otherY;
9	  return !sameCell && Math.abs(x - otherX) <= 1 && Math.abs(y - otherY) <= 1;
10	}
11	
12	function countLiveNeighbors(cell: Cell, livingCells: Cell[]): number {
13	  return livingCells.filter((other) => isNeighbor(cell, other)).length;
14	}
15	
16	function survives(liveNeighbors: number): boolean {
17	  return (
18	    liveNeighbors >= UNDERPOPULATION_THRESHOLD &&
19	    liveNeighbors <= OVERPOPULATION_THRESHOLD
20	  );
21	}
22	
23	function reproduces(liveNeighbors: number): boolean {
24	  return liveNeighbors === REPRODUCTION_NEIGHBOR_COUNT;
25	}
26	
27	function neighborhoodOf([x, y]: Cell): Cell[] {
28	  const offsets = [-1, 0, 1];
29	  return offsets.flatMap((dx) => offsets.map((dy): Cell => [x + dx, y + dy]));
30	}
31	
32	function candidateCells(livingCells: Cell[]): Cell[] {
