46	export function nextGeneration(cells: Cell[]): Cell[] {
47	  return candidateCells(cells).filter((cell) => {
48	    const liveNeighbors = countLiveNeighbors(cell, cells);
49	    return isAlive(cell, cells)
50	      ? survives(liveNeighbors)
51	      : reproduces(liveNeighbors);
52	  });
53	}
