  for (const cell of livingCells.flatMap(neighborhoodOf)) {
    candidates.set(String(cell), cell);
  }
  return [...candidates.values()];
}

function isAlive(cell: Cell, livingCells: Cell[]): boolean {
  return livingCells.some(
    ([x, y]) => x === cell[0] && y === cell[1],
  );
}

